 * Runs the instant-runoff count described in the task: each round tallies
 * every ballot for its most-preferred continuing candidate, a majority of
 * the active total wins, and otherwise the round's last-place candidate is
 * eliminated (breaking ties by comparing every round counted so far).
 */

/**
 * @param {{candidates: string[], ballots: {count: number, names: string[]}[]}} election
 * @returns {{rounds: {counts: Map<string, number>, exhausted: number, eliminated: string|null}[], winner: string|null}}
 */
export function runElection({ candidates, ballots }) {
  let continuing = new Set(candidates)
  const roundHistory = []
  const rounds = []
  let winner = null

  for (;;) {
    const counts = new Map()
    for (const name of continuing) counts.set(name, 0)
    let exhausted = 0

    for (const ballot of ballots) {
      const choice = ballot.names.find((name) => continuing.has(name))
      if (choice === undefined) {
        exhausted += ballot.count
      } else {
        counts.set(choice, counts.get(choice) + ballot.count)
      }
    }

    roundHistory.push(counts)

    const activeTotal = [...counts.values()].reduce((a, b) => a + b, 0)

    let roundWinner = null
    if (activeTotal > 0) {
      for (const [name, votes] of counts) {
        if (votes * 2 > activeTotal) {
          roundWinner = name
          break
        }
      }
    }

    if (roundWinner !== null) {
      rounds.push({ counts, exhausted, eliminated: null })
      winner = roundWinner
      break
    }

    if (activeTotal === 0) {
      rounds.push({ counts, exhausted, eliminated: null })
      break
    }

    const eliminated = pickElimination(continuing, roundHistory)
    rounds.push({ counts, exhausted, eliminated })
    continuing = new Set([...continuing].filter((name) => name !== eliminated))
  }

  return { rounds, winner }
}

function pickElimination(continuing, roundHistory) {
  const current = roundHistory[roundHistory.length - 1]
  let fewest = Infinity
  for (const name of continuing) fewest = Math.min(fewest, current.get(name))
  let tied = [...continuing].filter((name) => current.get(name) === fewest)

  while (tied.length > 1) {
    let narrowed = false
    for (const roundCounts of roundHistory) {
      const values = tied.map((name) => roundCounts.get(name))
      const min = Math.min(...values)
      if (values.some((v) => v !== min)) {
        tied = tied.filter((name) => roundCounts.get(name) === min)
        narrowed = true
        break
      }
    }
    if (!narrowed) break
  }

  if (tied.length === 1) return tied[0]
  return tied.reduce((last, name) => (name > last ? name : last))
}
"}

