{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260921T233347Z/cell-RHxico/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js rounds` prints every round of the instant-runoff
 * count read from standard input, and `node src/cli.js tally` prints only how
 * many rounds ran and who won.
 */
import { parseElection, ParseError } from './parse.js'
import { runElection } from './rounds.js'

function readStdin() {
  return new Promise((resolve, reject) => {
    const chunks = []
    process.stdin.on('data', (chunk) => chunks.push(chunk))
    process.stdin.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')))
    process.stdin.on('error', reject)
  })
}

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function formatRoundLine(roundNumber, counts, exhausted) {
  const sorted = [...counts.entries()].sort((a, b) => {
    if (b[1] !== a[1]) return b[1] - a[1]
    return a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0
  })
  const parts = sorted.map(([name, votes]) => `${name}=${votes}`)
  parts.push(`exhausted=${exhausted}`)
  return `round ${roundNumber}: ${parts.join(' ')}`
}

async function main() {
  const mode = process.argv[2]
  if (mode !== 'rounds' && mode !== 'tally') {
    fail('usage: cli.js rounds|tally')
    return
  }

